"""The smoke checker validates generated bytes independently of the app."""
from __future__ import annotations
import importlib.util
import json
import os
from pathlib import Path
import subprocess
import sys
import pytest

ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location('smoke_bundle_check', ROOT / 'scripts/smoke_bundle.py')
smoke = importlib.util.module_from_spec(spec)
spec.loader.exec_module(smoke)


@pytest.fixture
def smoke_output(tmp_path):
    destination = tmp_path / 'fresh-smoke'
    environment = dict(os.environ, QT_QPA_PLATFORM='offscreen', PYTHONPATH=str(ROOT / 'src'))
    completed = subprocess.run([sys.executable, '-m', 'contact_sheet', '--smoke-test', str(destination)],
                               cwd=ROOT, env=environment, capture_output=True, text=True, timeout=60)
    assert completed.returncode == 0, completed.stderr
    return destination


def test_source_smoke_emits_independently_verifiable_outputs(smoke_output):
    result = smoke.verify_output(smoke_output)
    assert result['ok'] and result['pages'] == 2
    assert len(result['input_hashes_before']) == 13


def test_smoke_checker_detects_original_mutation(smoke_output):
    photo = next((smoke_output / 'inputs').glob('*.png'))
    photo.write_bytes(b'changed outside the app')
    with pytest.raises(RuntimeError, match='modified an input'):
        smoke.verify_output(smoke_output)


def test_smoke_refuses_existing_destination(tmp_path):
    sentinel = tmp_path / 'important.txt'
    sentinel.write_text('unchanged', encoding='utf-8')
    environment = dict(os.environ, QT_QPA_PLATFORM='offscreen', PYTHONPATH=str(ROOT / 'src'))
    completed = subprocess.run([sys.executable, '-m', 'contact_sheet', '--smoke-test', str(tmp_path)],
                               cwd=ROOT, env=environment, capture_output=True, text=True, timeout=30)
    assert completed.returncode != 0
    assert sentinel.read_text(encoding='utf-8') == 'unchanged'
    assert not (tmp_path / 'inputs').exists()
